-- Existing Hibernate schemas are adopted at version 0; fresh databases use the same migration.
create table if not exists app_users (enabled boolean not null, max_workload integer default 5, id bigint generated by default as identity, role varchar(16) not null check ((role in ('ADMIN','STUDENT','TECHNICIAN'))), student_number varchar(30), password_hash varchar(60) not null, name varchar(100) not null, responsibility varchar(100), email varchar(254) not null unique, availability varchar(255) check ((availability in ('AVAILABLE','BUSY','UNAVAILABLE'))), primary key (id), check (role <> 'TECHNICIAN' or (max_workload is not null)));
create table if not exists assignment_settings (id bigint not null, strategy varchar(255) not null check ((strategy in ('SKILL_BASED','LOAD_BASED'))), primary key (id));
create table if not exists audit_events (actor_id bigint, incident_id bigint, timestamp timestamp(6) with time zone not null, description varchar(5000), action varchar(255) not null, id varchar(255) not null, next varchar(255), previous varchar(255), primary key (id));
create table if not exists catalog_entries (enabled boolean not null, label varchar(100) not null, code varchar(255) not null, criticality varchar(255) not null check ((criticality in ('LOW','MEDIUM','HIGH'))), id varchar(255) not null, kind varchar(255) not null, primary key (id));
create table if not exists collaboration_requests (id bigint generated by default as identity, incident_id bigint not null, primary_technician_id bigint not null, proposed_technician_id bigint not null, requested_at timestamp(6) with time zone not null, reviewed_at timestamp(6) with time zone, reviewed_by_id bigint, reason varchar(2000) not null, responsibility varchar(2000) not null, review_notes varchar(2000), required_skill varchar(255) not null check ((required_skill in ('NETWORK','HARDWARE','SOFTWARE','DATABASE','AUTHENTICATION','SECURITY','APPLICATION_SUPPORT','CLOUD','STORAGE'))), status varchar(255) not null check ((status in ('PENDING','APPROVED','REJECTED','CANCELLED'))), primary key (id));
create table if not exists incident_collaborators (id bigint generated by default as identity, incident_id bigint not null, technician_id bigint not null, responsibility varchar(2000) not null, primary key (id), unique (incident_id, technician_id));
create table if not exists incident_feedback (rating integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, incident_id bigint not null unique, student_id bigint not null, comment varchar(1000), primary key (id));
create table if not exists incident_history (actor_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, incident_id bigint not null, description varchar(4500) not null, action varchar(255) not null, visibility varchar(255) not null check ((visibility in ('INTERNAL','STUDENT_VISIBLE'))), primary key (id));
create table if not exists incidents (resolution_target_minutes integer, response_target_minutes integer, acknowledged_at timestamp(6) with time zone, assigned_technician_id bigint, closed_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, reporter_id bigint not null, resolution_deadline timestamp(6) with time zone, resolved_at timestamp(6) with time zone, response_deadline timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, verified_at timestamp(6) with time zone, title varchar(100) not null, description varchar(2000) not null, resolution_steps varchar(2000), resolution_summary varchar(2000), affected_service varchar(255) not null check ((affected_service in ('CAMPUS_WIFI','STUDENT_PORTAL','LIBRARY','LAB_COMPUTERS','EMAIL','CAMPUS_NETWORK','AUTHENTICATION','OTHER'))), category varchar(255) not null check ((category in ('HARDWARE','SOFTWARE','NETWORK','DATABASE','CLOUD','SECURITY','AUTHENTICATION','APPLICATION','STORAGE','OTHER'))), impact varchar(255) not null check ((impact in ('LOW','MEDIUM','HIGH'))), priority varchar(255) not null check ((priority in ('PENDING','P1','P2','P3','P4'))), status varchar(255) not null check ((status in ('NEW','CLASSIFIED','ASSIGNED','ACKNOWLEDGED','IN_PROGRESS','RESOLVED','VERIFIED','CLOSED'))), urgency varchar(255) not null check ((urgency in ('LOW','MEDIUM','HIGH'))), primary key (id));
create table if not exists investigation_notes (author_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, incident_id bigint not null, content varchar(2000) not null, kind varchar(255) not null check ((kind in ('NOTE','INFORMATION_REQUEST','STUDENT_REPLY'))), visibility varchar(255) not null check ((visibility in ('INTERNAL','STUDENT_VISIBLE'))), primary key (id));
create table if not exists notification_deliveries (created_at timestamp(6) with time zone not null, incident_id bigint, read_at timestamp(6) with time zone, recipient_id bigint not null, message varchar(5000) not null, channel varchar(255) not null, delivery_status varchar(255) not null, id varchar(255) not null, title varchar(255) not null, type varchar(255) not null, primary key (id));
create table if not exists priority_settings (criticality_weight float(53) not null, impact_weight float(53) not null, urgency_weight float(53) not null, id bigint not null, strategy varchar(255) not null check ((strategy in ('MULTIPLICATIVE','WEIGHTED'))), primary key (id));
create table if not exists scheduled_events (incident_id bigint, occurred_at timestamp(6) with time zone, description varchar(5000), id varchar(255) not null, next_level varchar(255), type varchar(255), primary key (id));
create table if not exists sla_policies (resolution_minutes integer not null, response_minutes integer not null, priority varchar(255) not null check ((priority in ('PENDING','P1','P2','P3','P4'))), primary key (priority));
create table if not exists technician_skills (technician_id bigint not null, skill varchar(255) not null check ((skill in ('NETWORK','HARDWARE','SOFTWARE','DATABASE','AUTHENTICATION','SECURITY','APPLICATION_SUPPORT','CLOUD','STORAGE'))), unique (technician_id, skill));
create table if not exists transfer_requests (id bigint generated by default as identity, incident_id bigint not null, primary_technician_id bigint not null, proposed_technician_id bigint not null, requested_at timestamp(6) with time zone not null, reviewed_at timestamp(6) with time zone, reviewed_by_id bigint, handover_notes varchar(2000) not null, review_notes varchar(2000), reason varchar(255) not null check ((reason in ('HIGH_WORKLOAD','LACK_OF_EXPERTISE','UNAVAILABLE','INCORRECT_ASSIGNMENT','BETTER_SUITED_TECHNICIAN','OTHER'))), status varchar(255) not null check ((status in ('PENDING','APPROVED','REJECTED','CANCELLED'))), primary key (id));
create index if not exists audit_incident_idx on audit_events (incident_id, timestamp);
create index if not exists notification_recipient_idx on notification_deliveries (recipient_id, channel, created_at);
-- Additive upgrade for existing Phase 4 schemas; no rows are removed.
alter table app_users add column if not exists availability varchar(255);
alter table app_users add column if not exists max_workload integer default 5;
alter table incidents add column if not exists response_deadline timestamp with time zone;
alter table incidents add column if not exists resolution_deadline timestamp with time zone;
alter table incidents add column if not exists response_target_minutes integer;
alter table incidents add column if not exists resolution_target_minutes integer;
alter table audit_events alter column incident_id drop not null;
